mapper.select:
SELECT 'POLICY' AS allpcj, h.POLICY_APP_ID AS CODE, p.GOV_PROJECT_NAME AS TITLE, p.POLICY_REGI_FIRSTDAY AS START_DATE, DATE_ADD(p.POLICY_REGI_LASTDAY, INTERVAL 1 DAY) AS END_DATE, p.GOV_PROJECT_INFO AS INFO FROM POLICY_APP_HISTORY h JOIN GOV_SUPPORT_POLICY p ON h.GOV_PROJECT_CODE = p.GOV_PROJECT_CODE WHERE h.MEMBER_ID = #{memberId}
UNION ALL
SELECT 'CERT', h.CERT_EXAM_APP_ID, CONCAT(c.CERT_NAME, ' ', h.EXAM_SESSION), e.EXAM_REGI_FIRSTDAY, DATE_ADD(e.EXAM_REGI_LASTDAY, INTERVAL 1 DAY), c.CERT_INFO FROM CERT_EXAM_APP_HISTORY h JOIN CERT_EXAM e ON h.CERT_CODE = e.CERT_CODE AND h.EXAM_SESSION = e.EXAM_SESSION JOIN CERT c ON h.CERT_CODE = c.CERT_CODE WHERE h.MEMBER_ID = #{memberId}
UNION ALL
SELECT 'JOB', h.JOB_APP_ID, r.JOB_POSTING_NAME, r.JOB_REGI_FIRSTDAY, DATE_ADD(r.JOB_REGI_LASTDAY, INTERVAL 1 DAY), r.RECRUITMENT_INFO FROM JOB_APP_HISTORY h JOIN RECRUITMENT r ON h.JOB_POSTING_CODE = r.JOB_POSTING_CODE WHERE h.MEMBER_ID = #{memberId}
ORDER BY START_DATE
